function languageRegion(language:string){const primary=language.toLowerCase().split('-')[0];return ({ar:'sa',bg:'bg',ca:null,cs:'cz',da:'dk',de:'de',el:'gr',en:'gb',es:'es',et:'ee',eu:null,fa:'ir',fi:'fi',fr:'fr',ga:'ie',he:'il',hi:'in',hr:'hr',hu:'hu',id:'id',is:'is',it:'it',ja:'jp',ko:'kr',lt:'lt',lv:'lv',ms:'my',nl:'nl',no:'no',pl:'pl',pt:'pt',ro:'ro',ru:'ru',sk:'sk',sl:'si',sv:'se',sw:'ke',th:'th',tr:'tr',uk:'ua',vi:'vn',zh:'cn'} as Record<string,string|null>)[primary]}
function LanguageBadge({language}:{language?:string|null}){const region=language?languageRegion(language):null;return language&&region?<i className={`fi fi-${region} source-language-flag`} role="img" aria-label={`Langue ${language}`}/>:null}
