function ProviderPageRow({page,onReport}:{page:ProviderPage;onReport?:(button:HTMLButtonElement)=>void}){const provider=providerLabel(page.provider);const url=page.sourceUrl;return <div className="media-source-row media-provider-row" data-card-hover-surface="true">{url?<a className="media-source-link" href={url} target="_blank" rel="noreferrer"><ProviderIcon provider={page.provider}/><span><strong>{provider}</strong><small>Page utile de l’œuvre</small></span></a>:<div className="media-source-link"><ProviderIcon provider={page.provider}/><span><strong>{provider}</strong><small>Page fournisseur indisponible</small></span></div>}<div className="media-source-actions">{onReport&&<button type="button" className="icon-button" aria-label={`Signaler un problème avec ${provider}`} title="Signaler un problème" data-report-trigger onClick={event=>onReport(event.currentTarget)}><CircleAlert size={16}/></button>}{url&&<button type="button" className="icon-button" aria-label={`Copier l’URL ${provider}`} title={`Copier l’URL ${provider}`} onClick={()=>void copyText(url)}><Copy size={16}/></button>}</div></div>}
function FavoriteIcon({url}:{url:string}){let domain='';try{domain=new URL(url).hostname}catch{}return <DomainIcon domain={domain}/>}
function favoritePosition(favorite:LibraryFavorite){const kind=typeof favorite.progression?.kind==='string'?favorite.progression.kind:'';const raw=favorite.progression?.raw??favorite.progression?.number;if(raw===undefined||raw===null)return null;return `${kind==='episode'?'Épisode':kind==='volume'?'Volume':'Chapitre'} ${String(raw)}`}
function uniqueFavorites(favorites:LibraryFavorite[]){return [...new Map(favorites.map(favorite=>[`${favorite.bookmarkId}:${favorite.url}`,favorite])).values()]}
