function SourceRow({source,onReport}:{item:LibraryItem;source:LibrarySource;onReport?:(button:HTMLButtonElement)=>void}){const [copied,setCopied]=useState(false);const workUrl=source.workUrl??source.canonicalUrl;const copy=async()=>{await copyText(workUrl);setCopied(true);window.setTimeout(()=>setCopied(false),1800)};return <div className="media-source-row" data-card-hover-surface="true"><a className="media-source-link" href={workUrl} target="_blank" rel="noreferrer"><SourceIcon source={source}/><span><strong>{source.domain}</strong></span></a><div className="media-source-actions">{onReport&&<button type="button" className="icon-button" aria-label={`Signaler un problème avec ${source.domain}`} title="Signaler un problème" data-report-trigger onClick={event=>onReport(event.currentTarget)}><CircleAlert size={16}/></button>}<button type="button" className="icon-button" aria-label={copied?'URL de l’œuvre copiée':'Copier l’URL de l’œuvre'} title="Copier l’URL de l’œuvre" onClick={()=>void copy()}><Copy size={16}/></button></div>{copied&&<span className="media-source-confirmation" role="status">URL de l’œuvre copiée.</span>}</div>}
