function RelatedWorkCard({work,onSelect}:{work:RelatedWork;onSelect:(work:RelatedWork)=>void}){
  const card=useRef<HTMLButtonElement>(null);const frame=useRef<number>(0);const pointer=useRef<{x:number;y:number}|null>(null);const bounds=useRef<{left:number;top:number;right:number;bottom:number}|null>(null);const tracking=useRef(false);
  const reset=()=>{tracking.current=false;bounds.current=null;pointer.current=null;if(frame.current)cancelAnimationFrame(frame.current);frame.current=0;card.current?.style.setProperty('--discovery-tilt-x','0deg');card.current?.style.setProperty('--discovery-tilt-y','0deg');card.current?.classList.remove('is-discovery-tilting')};
  const update=(event:React.PointerEvent<HTMLButtonElement>)=>{if(event.pointerType==='touch')return;if(!tracking.current){const rect=event.currentTarget.getBoundingClientRect();bounds.current={left:rect.left,top:rect.top,right:rect.right,bottom:rect.bottom};tracking.current=true}const rect=bounds.current!;pointer.current={x:Math.max(0,Math.min(1,(event.clientX-rect.left)/Math.max(1,rect.right-rect.left))),y:Math.max(0,Math.min(1,(event.clientY-rect.top)/Math.max(1,rect.bottom-rect.top)))};if(frame.current)return;frame.current=requestAnimationFrame(()=>{frame.current=0;const node=card.current,point=pointer.current;if(!node||!point)return;node.style.setProperty('--discovery-tilt-x',`${(.5-point.y)*10}deg`);node.style.setProperty('--discovery-tilt-y',`${(point.x-.5)*12}deg`);node.classList.add('is-discovery-tilting')})};
  useEffect(()=>{const track=(event:PointerEvent)=>{const rect=bounds.current;if(!tracking.current||!rect)return;const margin=14;if(event.clientX<rect.left-margin||event.clientX>rect.right+margin||event.clientY<rect.top-margin||event.clientY>rect.bottom+margin)reset()};window.addEventListener('pointermove',track,{passive:true});return()=>{window.removeEventListener('pointermove',track);if(frame.current)cancelAnimationFrame(frame.current)}},[]);
  return <button ref={card} type="button" className="related-work-card card media-card" data-card-hover-surface="true" onPointerEnter={update} onPointerMove={update} onClick={()=>onSelect(work)} aria-label={`Afficher ${displayTitle(work.title)}`}><span className="poster"><span className="poster-visual"><Cover item={work}/></span><CardTopline item={work}/><span className="poster-copy"><strong>{displayTitle(work.title)}</strong><small>{work.type}</small></span></span></button>
}
