  const detailCache=useRef(new Map<string,LibraryItem>([[rootItem.id,rootItem]]));const requestSequence=useRef(0);
  const modalRef=useRef<HTMLElement>(null);const checkedUrls=useRef(new Set<string>());const [sourceOverrides,setSourceOverrides]=useState<Record<string,LibrarySource['status']>>({});
  const reportButton=useRef<HTMLButtonElement>(null);
